/* Dispatch into om/engine/eng.om. Every hosted build links src/cudapp_om_eng.c,
 * generated by om/units.sh, and that unit answers; the reference is strong, so a
 * hosted link without the binding fails instead of silently keeping C.
 *
 * Each shell keeps its C oracle behind its own default-OFF switch
 * CUDAPP_MIGRATION_PENDING_C_<PART>. The shell defines ENG_C_PART before this
 * include when its switch is set, and eng_on() is then 0 for that file. The
 * freestanding build (OMEGA_GPU_NO_POSIX) has no binding and keeps C.
 * Syscalls, MMIO, doorbells, pushbuffer stores and hook calls stay in the shell. */
#ifndef OMEGA_ENG_DEC_H
#define OMEGA_ENG_DEC_H

#include <stdint.h>
#include <string.h>

#define ENG_OP_WINIT 0u
#define ENG_OP_WPOLL 1u
#define ENG_OP_JOBV 2u
#define ENG_OP_PHASE 3u
#define ENG_OP_RESV 4u
#define ENG_OP_CACHE 5u
#define ENG_OP_SERVE 6u
#define ENG_OP_POIS 7u
#define ENG_OP_WAITED 8u
#define ENG_OP_CLEAN 9u
#define ENG_OP_SEQGE 10u
#define ENG_OP_LIFE 11u
#define ENG_OP_REQF 12u
#define ENG_OP_VIS 13u
#define ENG_OP_BWE 14u
#define ENG_OP_TOMS 15u
#define ENG_OP_FCLS 16u
#define ENG_OP_WENTER 17u
#define ENG_OP_SCAN 18u
#define ENG_OP_ROLE 19u
#define ENG_OP_M16REL 20u
#define ENG_OP_NEGO 21u
#define ENG_OP_PCHK 22u
#define ENG_OP_BUFCK 23u
#define ENG_OP_HOPEN 24u
#define ENG_OP_HCHK 25u
#define ENG_OP_SUBM 26u
#define ENG_OP_CONC 27u
#define ENG_OP_COUNT 28u

#if defined(OMEGA_GPU_NO_POSIX)

static inline int eng_on(void) { return 0; }

static inline int eng_ask(uint64_t op, const uint64_t *in, int nin, uint64_t w[16]) {
    (void)op;
    (void)in;
    (void)nin;
    memset(w, 0, 16u * sizeof w[0]);
    return 1;
}

#else

uint32_t omega_eng(uint64_t *result, const void *p0, uint64_t p0_n, void *p1, uint64_t p1_n);

static inline int eng_on(void) {
#if defined(ENG_C_PART)
    return 0;
#else
    return 1;
#endif
}

/* 0 when the unit answered and its int result is 0. Nonzero is a binding
 * failure; the caller must not invent a decision. */
static inline int eng_ask(uint64_t op, const uint64_t *in, int nin, uint64_t w[16]) {
    uint64_t m[24];
    uint64_t result = 1;
    uint32_t st;
    int i;
    memset(m, 0, sizeof m);
    memset(w, 0, 16u * sizeof w[0]);
    m[0] = op;
    for (i = 0; i < nin && i < 23; i++) m[1 + i] = in[i];
    st = omega_eng(&result, m, 24, w, 16);
    if (st != 0 || result != 0) return 1;
    return 0;
}

#endif
#endif
